insert into public.reference_passages
  (id, source_id, branch, personnel_category, occupation_code, occupation_title, section_type, rank_band, components, heading, chapter, body, body_sha256, pdf_page_start, pdf_page_end, printed_page, sort_order, effective_from, effective_to, cumulative, skill_level)
values
  ('ad301a9c-7c38-5690-8445-c001771f2adc', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'development', 'O-3', null, 'Captain — overview', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'All captain assignments are entry-level public affairs billets where new 46As can de- velop their trade in planning, executing, or providing counsel in the public affairs function. All Public Affairs Captain positions are considered KD, qualifying an officer as captain and making them competitive for selection to major.', 'a5b32c69d2c369a89c80c0e5e5a591ec0245bb707e28d85737837952e2c1435f', 3, 3, null, 0, null, null, false, null),
  ('18468881-e8c7-5bf3-875f-ead6c9188e26', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'training', 'O-3', null, 'Captain — Education', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'FA46 captains must attend the 9-week resident PACS-Q at DINFOS, Fort Meade, MD prior to their first Public Affairs assignment.', '20fe99280b83f50179e4990b8787666669560aa9a957ef8506bacf80a6038225', 3, 3, null, 1, null, null, false, null),
  ('b7cc69cd-c6c1-5640-a190-56cacc149b57', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'self_development', 'O-3', null, 'Captain — Self-Development', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'FA46 captains should conduct individual study, research, professional reading, practice, and self-assessment, in accordance with their independent development plan and professional goals. This may include the U.S. Army Chief of Staff’s Professional Reading List, as well as civilian Public Affairs training and credentialing opportunities with the Public Relations Society of America, International Association of Business Communicators, Toastmasters, or sim- ilar professional organizations.', '409dccf346961828f7adacc39106ca88e5702b5ac741d7420dc7c308c96c2fd2', 3, 4, null, 2, null, null, false, null),
  ('8d85e009-bb24-51a7-888f-0f1d07616439', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'development', 'O-4', null, 'Majors — overview', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'VTIP FA46 majors must attend the 9-week, resident PACS-Q at DINFOS, Fort Meade, MD, prior to their first Public Affairs assignment.', '3ac9f7e3eac8b64bdf7de573911938d3c31abf768c126f16e004eb0523f01730', 4, 4, null, 3, null, null, false, null),
  ('4aa61224-2a08-521c-9906-b9feb32171d4', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'training', 'O-4', null, 'Majors — Education', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', '(a) FA46 majors must complete Military Education Level 4 (MEL-4) to be educationally qual- ified for selection to lieutenant colonel. High performing officers will be selected by a DA board to attend the 10-month resident Command and General Staff Officers College (CGSOC) at Fort Leavenworth, KS. The DA board will also identify which FA46 officers will complete CGSOC through the 14-week CGSOC Common Core-Satellite course at either Fort Leavenworth, Fort Belvoir, or Redstone Arsenal. Currently, PACS-Q is the FA46 MEL-4 Advanced Operations Course credentialing course. Upon completion of both PACS-Q and CGSOC-CC or a sister ser- vice/approved foreign-nation resident course, 46As will be coded B1 on their personnel records and awarded Joint Professional Military Education (JPME) Phase I credit.
(b) FA46 majors should seek a graduate degree in strategic communication to be most competitive amongst their peers. Graduate program coursework should focus on practical skills and how communication theories and research are integrated into strategic communication initi- atives.', 'af69845f0db573d4f012906e45c248a6076aee363b47d8dca13e51ca36b64424', 4, 4, null, 4, null, null, false, null),
  ('1281609f-8982-553a-ad31-7f406e1942ca', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'assignments', 'O-4', null, 'Majors — Assignments', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'FA46 majors serve primarily in operational assignments and should aggres- sively seek key assignments in which they are the principal spokesperson for operational units, staff for higher echelon operational units, or Mobile Public Affairs Detachment commanders. How- ever, all major billets are KD.', 'b4ff735fa9f3827e877ef1b2f3dd8317c2b474e5c5d1c6c9a7c17d12e64784c3', 4, 4, null, 5, null, null, false, null),
  ('c08c7b34-d10d-525d-bcb0-451ecbb6cdd6', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'self_development', 'O-4', null, 'Majors — Self-Development', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', '(a) FA46 majors should seek opportunities to attend the DINFOS Joint Contingency Public Affairs Course, Joint Intermediate Public Affairs Course, the Advanced Military Studies Program at the School of Advanced Military Studies, Red Team Leader or Member course at the University of Foreign Military and Cultural Studies, or any other courses that increases an officer’s ability to advise organizational principals, synchronize communications at the operational and strategic levels, develop Public Affairs Guidance, and plan and lead Public Affairs operations.
(b) FA46 majors should continue pursuing civilian Public Affairs training and credentialing opportunities with the Public Relations Society of America, International Association of Business Communicators, Toastmasters, and similar professional organizations.', '4e4a38b94c16f62e931bcaf315d9b261eb80bff3872a0a57905b5879d8ef0940', 4, 4, null, 6, null, null, false, null),
  ('370d0791-25c4-5268-be15-e6b9c6670b3a', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'development', 'O-5', null, 'Lieutenant Colonel — overview', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'FA46 officers are that are ILE (common core and PACS-Q) complete are eligible to compete in the operations support functional category for promotion to colonel if they have 24 months cumulative Public Affairs experience prior to consideration for promotion to colo- nel.', '6a42010f6bad092eacfcc79e066fbadde6fed902cb39f382d9f8a531ef193812', 4, 4, null, 7, null, null, false, null),
  ('a0c094fa-d702-51d1-a4c0-3cf4a8111aec', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'training', 'O-5', null, 'Lieutenant Colonel — Education', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'Lieutenant colonels are expected to complete/compete for:
(a) Joint Intermediate Public Affairs Course
(b) Joint Contingency Public Affairs Course
(c) Complete JPME II
(d) Senior Service College (SSC) selection.', 'bdf3ca0102854da4bf5a21cc9938603993522b08c3c3f7dafe2311780ad83623', 4, 4, null, 8, null, null, false, null),
  ('13cb0ea1-9904-599c-b859-6764c399eb66', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'assignments', 'O-5', null, 'Lieutenant Colonel — Assignments', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'FA46 lieutenant colonels are generally assigned to senior staff positions, where they can fully use their knowledge of the Army and their FA. PAOs who have demonstrated high potential will be assigned to flag officer level commands and nominative positions on head- quarters, DoD, and joint staffs. Lieutenant colonels are encouraged to seek Public Affairs assign- ments within joint commands to gain joint and combined command exposure and experience. All authorized lieutenant colonel public affairs positions are KD, with 24 months of experience quali- fying an officer for consideration for promotion to colonel.', '7361e47724ad42a8fdc0f27b4c69b7c442964786471626c537e9f6c184eb8755', 4, 5, null, 9, null, null, false, null),
  ('83dac525-febc-5c43-af13-6ee0dd30551a', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'self_development', 'O-5', null, 'Lieutenant Colonel — Self-Development', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'Lieutenant colonels are expected to:
(a) Complete, if not completed already, the Joint Intermediate Public Affairs and Joint Contingency Public Affairs courses.
(b) Highly encouraged to apply for and complete the Joint and Combined Warfighting School at the Joint Forces Staff College.
(c) Complete a graduate degree in a Public Affairs related discipline.
(d) Complete civilian Public Affairs credentials such as Public Relations Society of America or International Association of Business Communicators, and similar professional or- ganizations.', '0a8e4131b93e9a4a54d89d21d4e56290049cee50489f5020a3f1030f0c269e3c', 5, 5, null, 10, null, null, false, null),
  ('385132f1-b6d2-5535-8400-5eef92d40cbb', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'development', 'O-6', null, 'Colonel — overview', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'Public Affairs colonels are the senior practitioners and are considered the experts in the functional area. FA46 colonels primarily serve as PAOs to general/flag officers (GO/FO) and senior executive civilians at major Army and DoD commands and agencies. All authorized 46A po- sitions are KD and will qualify PA colonels for consideration for the most senior leadership and man- agement positions the Army can offer.', '5b83e6f670d607131f1a39d722426ef46e07c9471032ca300808e290b0dc810a', 5, 5, null, 11, null, null, false, null),
  ('837537a2-f639-5729-b840-27057785cb6e', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'training', 'O-6', null, 'Colonel — Education', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'All FA46 colonels should complete SSC (MEL-1) in residence at the Army War College (AWC), National Defense University (NDU), or any other sister service senior college; or in non-residence through the Department of Distance Education (DDE) through the AWC.', '7e2ee0f5e1219ec94caaf2410b0ea597f161ca850b045f02e666d98450b4c973', 5, 5, null, 12, null, null, false, null),
  ('273a720b-bccf-552f-89a1-06aa817a365f', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'assignments', 'O-6', null, 'Colonel — Assignments', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'FA46 colonels are generally assigned to senior staff positions, where they can fully use their knowledge of the Army and their FA. PAOs who have demonstrated high potential will be assigned to GO/FO level commands and nominative positions on headquarters, DoD and joint staffs. Colonels are encouraged to seek Public Affairs assignments within joint commands to gain joint and combined command exposure and experience.', '6f6a7c20ed41154894784dee657d2248f8645e937dd3f41dad8b27547f986bdf', 5, 5, null, 13, null, null, false, null),
  ('4707b3a3-0bc9-560b-a44c-9c43a311450d', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'development', 'O-6', null, 'Colonel — Key/Developmental', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'FA46 Colonels serve as senior leaders providing wisdom, experi- ence, vision, and mentorship mastered over many years.', '5fa93775aa3c5bdcca23fed6f862b48075b40d477fbfbf06eb4f39ff61082557', 5, 5, null, 14, null, null, false, null),
  ('748d1145-b113-5feb-ab58-283d5ee71a60', 'f4c88bb1-75e5-5259-9d6c-e26284b40322', 'Army', 'officer', '46A', 'PUBLIC AFFAIRS, GENERAL', 'self_development', 'O-6', null, 'Colonel — Self-Development', 'Public Affairs Functional Area (FA46) career pamphlet, DA PAM 600-3 chapter (29 September 2023)', 'Colonels should continue to pursue professional experience by partic- ipation and leadership in the Public Relations Society of America or the International Association of Business Communicators, and pursue Joint, interagency, intergovernmental, and multinational as- signments, exercises, and operations. Additionally, FA46 colonels are strongly recommended to conduct research on strategic communications issues and seek to have their research published in a peer-reviewed journal. Research-based self-development not only enhance the analytical and critical thinking skills of officers but also furthers the professionalization of the Public Affairs career field.', '973081fb403f79deefc5f750443044c5bbabbf96b25fddeb6ca6b63c0bb2a419', 5, 5, null, 15, null, null, false, null);
